$repoRoot = [System.IO.Path]::GetFullPath((Get-Location).ProviderPath)
if (-not [System.IO.Path]::IsPathFullyQualified($repoRoot)) {
    throw 'The repository root must be an absolute path.'
}

$contract = Join-Path $repoRoot 'modules/self-hosted-model-operations/lab/serving-contract'
if (-not (Test-Path -LiteralPath $contract -PathType Container)) {
    throw "The serving-contract directory is missing. Start at the repository root: $contract"
}

if ($PSVersionTable.PSVersion -lt [version]'7.6') {
    throw "PowerShell 7.6 or newer is required; observed $($PSVersionTable.PSVersion)"
}
if (-not (Get-Command python -ErrorAction SilentlyContinue)) {
    throw 'Python must be available through the python command.'
}
$pythonVersionText = (& python -c "import sys; print('.'.join(map(str, sys.version_info[:3])))").Trim()
if ($LASTEXITCODE -ne 0) {
    throw "Python preflight failed with exit code $LASTEXITCODE"
}
$pythonVersion = [version]$pythonVersionText
if ($pythonVersion -lt [version]'3.11') {
    throw "Python 3.11 or newer is intended; observed $pythonVersionText"
}

$requiredFiles = @(
    'Setup-ServingLab.ps1',
    'Start-ServingLab.ps1',
    'Stop-ServingLab.ps1',
    'Invoke-ServingChild.ps1',
    'Serving-Time.ps1',
    'Test-ServingLifecycle.ps1',
    'conformance.py',
    'test_conformance.py'
)
foreach ($name in $requiredFiles) {
    $requiredPath = Join-Path $contract $name
    if (-not (Test-Path -LiteralPath $requiredPath -PathType Leaf)) {
        throw "Required supplied file is missing: $requiredPath"
    }
}

$runsParent = Join-Path $repoRoot 'lab-runs'
New-Item -ItemType Directory -Path $runsParent -Force -ErrorAction Stop | Out-Null
$runId = [guid]::NewGuid().ToString('N')
$runRoot = Join-Path $runsParent ("serving-run-$runId")
if (Test-Path -LiteralPath $runRoot) {
    throw "The generated run root already exists and will not be reused: $runRoot"
}
New-Item -ItemType Directory -Path $runRoot -ErrorAction Stop | Out-Null

$workspace = Join-Path $runRoot 'workspace'
$evidence = Join-Path $runRoot 'evidence'
if (Test-Path -LiteralPath $workspace) {
    throw "Setup requires a nonexistent workspace: $workspace"
}
if (Test-Path -LiteralPath $evidence) {
    throw "Evidence path unexpectedly exists: $evidence"
}
New-Item -ItemType Directory -Path $evidence -ErrorAction Stop | Out-Null

$os = Get-CimInstance Win32_OperatingSystem
$cpu = Get-CimInstance Win32_Processor | Select-Object -First 1
$computerSystem = Get-CimInstance Win32_ComputerSystem
$repoDriveName = (Split-Path -Qualifier $repoRoot).TrimEnd(':')
$inventory = [ordered]@{
    evidenceClass = 'ACTUAL_LOCAL'
    observedAtUtc = (Get-Date).ToUniversalTime().ToString('o')
    os = [ordered]@{
        caption = $os.Caption
        version = $os.Version
        buildNumber = $os.BuildNumber
        architecture = $os.OSArchitecture
    }
    cpu = [ordered]@{
        name = $cpu.Name
        logicalProcessors = $cpu.NumberOfLogicalProcessors
    }
    totalPhysicalMemoryBytes = [uint64]$computerSystem.TotalPhysicalMemory
    freeBytesOnRepositoryDrive = [uint64](Get-PSDrive -Name $repoDriveName).Free
    powershellVersion = $PSVersionTable.PSVersion.ToString()
    dotnetVersion = [System.Environment]::Version.ToString()
    pythonVersion = $pythonVersionText
    automaticallyUploaded = $false
}
$inventoryPath = Join-Path $evidence 'inventory.json'
$inventory | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $inventoryPath -Encoding utf8

Write-Host "Repository root: $repoRoot"
Write-Host "Run root: $runRoot"
Write-Host "Reserved workspace: $workspace"
Write-Host "Local evidence: $evidence"
Write-Host "Inventory: $inventoryPath"

if ($null -eq $repoRoot -or $null -eq $runRoot -or $null -eq $workspace -or $null -eq $evidence) {
    throw 'Run the preflight in this same PowerShell session first.'
}
$contract = Join-Path $repoRoot 'modules/self-hosted-model-operations/lab/serving-contract'
Set-Location -LiteralPath $contract

if (Test-Path -LiteralPath $workspace) {
    throw "The baseline workspace must not exist before Setup: $workspace"
}
.\Setup-ServingLab.ps1 -Workspace $workspace
# Optional alternative only when an approved cache already exists:
# .\Setup-ServingLab.ps1 -Workspace $workspace -ArtifactCache 'D:\p42-artifact-cache'

python -m unittest -v test_conformance.py
if ($LASTEXITCODE -ne 0) {
    throw "Synthetic conformance tests failed with exit code $LASTEXITCODE"
}

$receipt = Join-Path $evidence 'receipt-11842-live.json'
$authEvidence = Join-Path $evidence 'authentication-11842.json'
foreach ($newEvidencePath in @($receipt, $authEvidence)) {
    if (Test-Path -LiteralPath $newEvidencePath) {
        throw "Refusing to overwrite evidence: $newEvidencePath"
    }
}

$rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
$keyBytes = New-Object byte[] 32
$badBytes = New-Object byte[] 32
$baselineStarted = $false
try {
    $rng.GetBytes($keyBytes)
    $env:P42_SERVING_API_KEY = [Convert]::ToBase64String($keyBytes)

    do {
        $rng.GetBytes($badBytes)
        $badKey = [Convert]::ToBase64String($badBytes)
    } while ($badKey -ceq $env:P42_SERVING_API_KEY)

    .\Start-ServingLab.ps1 -Workspace $workspace -Port 11842
    $baselineStarted = $true

    $wrongKeyResponse = Invoke-WebRequest `
        -Uri 'http://127.0.0.1:11842/v1/models' `
        -Method Get `
        -Headers @{ Authorization = "Bearer $badKey" } `
        -SkipHttpErrorCheck `
        -TimeoutSec 10
    if ($wrongKeyResponse.StatusCode -ne 401) {
        throw "Expected wrong-key HTTP 401; observed $($wrongKeyResponse.StatusCode)"
    }

    $sameKeyResponse = Invoke-WebRequest `
        -Uri 'http://127.0.0.1:11842/v1/models' `
        -Method Get `
        -Headers @{ Authorization = "Bearer $env:P42_SERVING_API_KEY" } `
        -SkipHttpErrorCheck `
        -TimeoutSec 10
    if ($sameKeyResponse.StatusCode -ne 200) {
        throw "Expected same-key HTTP 200; observed $($sameKeyResponse.StatusCode)"
    }
    $modelsDocument = $sameKeyResponse.Content | ConvertFrom-Json
    $modelIds = @($modelsDocument.data | ForEach-Object { $_.id })
    if ($modelIds -notcontains 'p42-qwen3-06b') {
        throw 'The authenticated models endpoint did not return alias p42-qwen3-06b.'
    }

    [ordered]@{
        evidenceClass = 'ACTUAL_LOCAL'
        endpoint = '/v1/models'
        wrongGeneratedKeyStatus = [int]$wrongKeyResponse.StatusCode
        sameSessionKeyStatus = [int]$sameKeyResponse.StatusCode
        authenticatedAlias = 'p42-qwen3-06b'
        credentialsRecorded = $false
    } | ConvertTo-Json | Set-Content -LiteralPath $authEvidence -Encoding utf8

    $badKey = $null
    [Array]::Clear($badBytes, 0, $badBytes.Length)

    python conformance.py --port 11842 --output $receipt
    if ($LASTEXITCODE -ne 0) {
        throw "Live conformance failed with exit code $LASTEXITCODE"
    }
} finally {
    try {
        $statePath = Join-Path $workspace 'server-state.json'
        if ($baselineStarted -and (Test-Path -LiteralPath $statePath -PathType Leaf)) {
            .\Stop-ServingLab.ps1 -Workspace $workspace
        }
    } finally {
        Remove-Item Env:P42_SERVING_API_KEY -ErrorAction SilentlyContinue
        $badKey = $null
        [Array]::Clear($badBytes, 0, $badBytes.Length)
        [Array]::Clear($keyBytes, 0, $keyBytes.Length)
        $rng.Dispose()
    }
}

$lifecycleTestRoot = Join-Path $evidence ("lifecycle-11842-" + [guid]::NewGuid().ToString('N'))
if (Test-Path -LiteralPath $lifecycleTestRoot) {
    throw "Lifecycle TestRoot must be new: $lifecycleTestRoot"
}
New-Item -ItemType Directory -Path $lifecycleTestRoot -ErrorAction Stop | Out-Null

$lifecycleRng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
$lifecycleKeyBytes = New-Object byte[] 32
try {
    $lifecycleRng.GetBytes($lifecycleKeyBytes)
    $env:P42_SERVING_API_KEY = [Convert]::ToBase64String($lifecycleKeyBytes)
    .\Test-ServingLifecycle.ps1 -Workspace $workspace -TestRoot $lifecycleTestRoot -Port 11842
} finally {
    Remove-Item Env:P42_SERVING_API_KEY -ErrorAction SilentlyContinue
    [Array]::Clear($lifecycleKeyBytes, 0, $lifecycleKeyBytes.Length)
    $lifecycleRng.Dispose()
}

Write-Host "Baseline receipt: $receipt"
Write-Host "Redacted authentication evidence: $authEvidence"
Write-Host "Lifecycle evidence: $lifecycleTestRoot"

$contract = Join-Path $repoRoot 'modules/self-hosted-model-operations/lab/serving-contract'
Set-Location -LiteralPath $contract
if (-not (Test-Path -LiteralPath $receipt -PathType Leaf)) {
    throw "Baseline receipt is missing: $receipt"
}
$live = Get-Content -LiteralPath $receipt -Raw | ConvertFrom-Json
if (@($live.checks).Count -ne 12) {
    throw "Expected 12 receipt checks; observed $(@($live.checks).Count)"
}
$live.checks | Select-Object name, state | Format-Table -AutoSize

$expectedObserved = @(
    'health_public',
    'authentication_rejection',
    'server_identity',
    'bounded_completion',
    'stream',
    'early_disconnect',
    'recovery_after_disconnect',
    'overload_observation'
)
foreach ($name in $expectedObserved) {
    $entry = @($live.checks | Where-Object name -eq $name)
    if ($entry.Count -ne 1 -or $entry[0].state -ne 'observed') {
        throw "Required live observation is absent: $name"
    }
}

$timeoutEntry = @($live.checks | Where-Object name -eq 'client_timeout')
if ($timeoutEntry.Count -ne 1) {
    throw 'Exactly one client_timeout entry is required.'
}
if ($timeoutEntry[0].state -ne 'observed') {
    throw "The timeout experiment was not observed on this machine; recorded state: $($timeoutEntry[0].state)"
}

foreach ($name in @('server_side_cancellation', 'stop_restart_recovery', 'artifact_hashes')) {
    $entry = @($live.checks | Where-Object name -eq $name)
    if ($entry.Count -ne 1 -or $entry[0].state -ne 'not-observed') {
        throw "The port-only receipt must retain separate evidence as not-observed: $name"
    }
}

if ($null -eq $repoRoot -or $null -eq $runRoot -or $null -eq $workspace -or $null -eq $evidence) {
    throw 'Continue in the same PowerShell session used for the baseline.'
}
$contract = Join-Path $repoRoot 'modules/self-hosted-model-operations/lab/serving-contract'
Set-Location -LiteralPath $contract
if (-not (Test-Path -LiteralPath $workspace -PathType Container)) {
    throw "The actual verified baseline workspace is missing: $workspace"
}

$statePath = Join-Path $workspace 'server-state.json'
if (Test-Path -LiteralPath $statePath -PathType Leaf) {
    throw 'Baseline state still exists. Resolve it with the same-key ownership-checked baseline cleanup before starting this changed task.'
}

$oldClient = [System.Net.Sockets.TcpClient]::new()
$oldPortRefused = $false
$completed = $false
try {
    $oldAttempt = $oldClient.ConnectAsync('127.0.0.1', 11842)
    try {
        $completed = $oldAttempt.Wait(5000)
    } catch {
        $baseException = $_.Exception.GetBaseException()
        if ($baseException -is [System.Net.Sockets.SocketException] -and
            $baseException.SocketErrorCode -eq [System.Net.Sockets.SocketError]::ConnectionRefused) {
            $oldPortRefused = $true
        } else {
            throw
        }
    }

    if (-not $oldPortRefused) {
        if (-not $completed) {
            throw 'The 11842 probe exceeded five seconds. Timeout is not proof of closure.'
        }
        if ($oldClient.Connected -or $oldAttempt.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
            throw 'Port 11842 accepted a connection and is not proven closed.'
        }
        if ($oldAttempt.IsFaulted) {
            $baseException = $oldAttempt.Exception.GetBaseException()
            if ($baseException -is [System.Net.Sockets.SocketException] -and
                $baseException.SocketErrorCode -eq [System.Net.Sockets.SocketError]::ConnectionRefused) {
                $oldPortRefused = $true
            } else {
                throw $oldAttempt.Exception
            }
        }
    }
    if (-not $oldPortRefused) {
        throw 'Port 11842 closure was not proven by SocketError.ConnectionRefused.'
    }
} finally {
    $oldClient.Dispose()
}

$changedEvidence = Join-Path $runRoot ("evidence-port11901-" + [guid]::NewGuid().ToString('N'))
if (Test-Path -LiteralPath $changedEvidence) {
    throw "Changed evidence directory must be new: $changedEvidence"
}
New-Item -ItemType Directory -Path $changedEvidence -ErrorAction Stop | Out-Null
$receipt11901 = Join-Path $changedEvidence 'receipt-11901-live.json'
if (Test-Path -LiteralPath $receipt11901) {
    throw "Refusing to overwrite changed-port receipt: $receipt11901"
}

$changedRng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
$changedKeyBytes = New-Object byte[] 32
$changedStarted = $false
try {
    $changedRng.GetBytes($changedKeyBytes)
    $env:P42_SERVING_API_KEY = [Convert]::ToBase64String($changedKeyBytes)

    .\Start-ServingLab.ps1 -Workspace $workspace -Port 11901
    $changedStarted = $true

    python conformance.py --port 11901 --output $receipt11901
    if ($LASTEXITCODE -ne 0) {
        throw "Unchanged conformance failed on port 11901 with exit code $LASTEXITCODE"
    }

    $changed = Get-Content -LiteralPath $receipt11901 -Raw | ConvertFrom-Json
    if ([int]$changed.port -ne 11901) {
        throw "Receipt port mismatch; expected 11901, observed $($changed.port)"
    }
    if (@($changed.checks).Count -ne 12) {
        throw "Expected 12 changed-port checks; observed $(@($changed.checks).Count)"
    }

    $requiredChangedObserved = @(
        'health_public',
        'authentication_rejection',
        'server_identity',
        'bounded_completion',
        'stream',
        'early_disconnect',
        'recovery_after_disconnect',
        'overload_observation'
    )
    foreach ($name in $requiredChangedObserved) {
        $entry = @($changed.checks | Where-Object name -eq $name)
        if ($entry.Count -ne 1 -or $entry[0].state -ne 'observed') {
            throw "Changed-port observation is absent: $name"
        }
    }

    $identity = @($changed.checks | Where-Object name -eq 'server_identity')
    if ($identity.Count -ne 1 -or $identity[0].alias -ne 'p42-qwen3-06b') {
        throw 'Changed-port authenticated identity is not p42-qwen3-06b.'
    }

    $timeout = @($changed.checks | Where-Object name -eq 'client_timeout')
    if ($timeout.Count -ne 1) {
        throw 'Changed receipt must contain exactly one client_timeout check.'
    }
    if ($timeout[0].state -ne 'observed') {
        throw "The changed-port timeout experiment was unmet; recorded state: $($timeout[0].state)"
    }

    $cancellation = @($changed.checks | Where-Object name -eq 'server_side_cancellation')
    if ($cancellation.Count -ne 1 -or $cancellation[0].state -ne 'not-observed') {
        throw 'Do not upgrade server-side cancellation beyond the receipt evidence.'
    }
} finally {
    try {
        if ($changedStarted -and (Test-Path -LiteralPath $statePath -PathType Leaf)) {
            .\Stop-ServingLab.ps1 -Workspace $workspace
        }
    } finally {
        Remove-Item Env:P42_SERVING_API_KEY -ErrorAction SilentlyContinue
        [Array]::Clear($changedKeyBytes, 0, $changedKeyBytes.Length)
        $changedRng.Dispose()
    }
}

$restartTestRoot = Join-Path $changedEvidence ("lifecycle-restart-11901-" + [guid]::NewGuid().ToString('N'))
if (Test-Path -LiteralPath $restartTestRoot) {
    throw "Restart TestRoot must be new: $restartTestRoot"
}
New-Item -ItemType Directory -Path $restartTestRoot -ErrorAction Stop | Out-Null

$restartRng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
$restartKeyBytes = New-Object byte[] 32
try {
    $restartRng.GetBytes($restartKeyBytes)
    $env:P42_SERVING_API_KEY = [Convert]::ToBase64String($restartKeyBytes)
    .\Test-ServingLifecycle.ps1 -Workspace $workspace -TestRoot $restartTestRoot -Port 11901
} finally {
    Remove-Item Env:P42_SERVING_API_KEY -ErrorAction SilentlyContinue
    [Array]::Clear($restartKeyBytes, 0, $restartKeyBytes.Length)
    $restartRng.Dispose()
}

Write-Host "Fresh changed-port evidence: $changedEvidence"
Write-Host "Changed-port receipt: $receipt11901"
Write-Host "Changed-port lifecycle and restart evidence: $restartTestRoot"
Write-Host 'The owned service is stopped, and the original baseline workspace remains available for verified reuse.'
